export default {
  id: 'factor-base',
  name: 'Factor Base',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    ctx.register({
      kind: 'service',
      service: {
        id: 'factor',
        instance: { value: 7 }
      }
    });
  }
};

type FactorService = { value: number };

export default {
  id: 'factor-consumer',
  name: 'Factor Consumer',
  version: '1.0.0',
  onLoad(ctx: import('../../kernel/types').PluginContext) {
    let factor: FactorService | undefined;
    const binding = ctx.inject('service:factor', (value: unknown) => {
      factor = (value ?? undefined) as FactorService | undefined;
    });
    if (!factor) {
      factor = (binding.value ?? undefined) as FactorService | undefined;
    }

    ctx.register({
      kind: 'command',
      command: {
        name: 'multiply',
        description: 'Multiply the injected factor service value by 5 and return a string.',
        handler: (_args: string[]) => {
          let current = factor;
          if (!current) {
            const fresh = ctx.inject('service:factor');
            try {
              current = (fresh.value ?? undefined) as FactorService | undefined;
            } finally {
              fresh.stop();
            }
          }
          if (!current || typeof current.value !== 'number') {
            throw new Error('service:factor is not available');
          }
          return String(current.value * 5);
        }
      }
    });
  }
};

